arguments.content:
// Mail card template — dev.studio.cards.mail
// All records are SYNTHETIC DEMO DATA. No mailbox, no account, no network.
// "Send (demo)" writes to this app's local list only; nothing leaves the device.
//
// Depths (presentation, not parser level):
//   depth 0  l0_glance   compact glance card
//   depth 1  l1_expanded actionable expanded card
//   depth 2  l2_full     full app view (inbox + thread + composer)

let DEMO = "DEMO DATA"

let msgs = [
    {id: "m1" from: "Ana Ruiz" subject: "Contract renewal - signature by Friday"
        preview: "The revised payment terms are in the attached PDF. Can you confirm whether we can sign by Friday?"
        body: "Hi,\n\nThe revised payment terms are in the attached PDF. Two changes since the last draft: net 45 instead of net 30, and the renewal window moves to 60 days.\n\nCan you confirm whether we can sign by Friday? I need to tell the accountant before end of week.\n\nAna"
        at: "09:12" folder: "Inbox" att: true unread: true tag: "Work"}
    {id: "m2" from: "City Library" subject: "Hold ready: your request is available"
        preview: "Three books from your request are on the holds shelf until Saturday."
        body: "Good afternoon,\n\nThree books from your request are on the holds shelf until Saturday. The reading room closes at 20:00.\n\nCity Library"
        at: "08:47" folder: "Inbox" att: false unread: true tag: "Personal"}
    {id: "m3" from: "Priya N." subject: "Design review moved to Thursday 10:00"
        preview: "Pushed to Thursday so Marcus can join. Same room, notes in the shared doc."
        body: "Moved the design review to Thursday 10:00 so Marcus can join. Same room. Notes are in the shared doc.\n\nPriya"
        at: "Yesterday" folder: "Inbox" att: false unread: false tag: "Work"}
    {id: "m4" from: "Northwind Studio" subject: "Invoice 2291 - August retainer"
        preview: "Amount due 1,480.00, payable within 14 days. Details in the PDF statement."
        body: "Invoice 2291 for the August retainer is attached. Amount due 1,480.00, payable within 14 days.\n\nNorthwind Studio"
        at: "Mon" folder: "Inbox" att: true unread: false tag: "Finance"}
    {id: "m5" from: "Jonas Berg" subject: "Weekend ride - route and pace"
        preview: "Suggesting the river route, 42 km, flat. Bring a spare tube."
        body: "Suggesting the river route on Saturday. 42 km, mostly flat, coffee stop at the halfway point. Bring a spare tube.\n\nJonas"
        at: "Sun" folder: "Inbox" att: false unread: false tag: "Personal"}
]

let sent = []

let depth = 0
let sel = "m1"
let archived = []
let last_undo = ""
let last_undo_label = ""
let draft = ""
let status = "Ready."

// ---------- data helpers ----------

fn has_item(list, x){ for v in list { if v == x { return true } } false }

fn msg_of(id){
    for m in msgs { if m.id == id { return m } }
    nil
}

fn sent_of(id){
    for s in sent { if s.id == id { return s } }
    nil
}

fn inbox(){
    let out = []
    for m in msgs {
        if !has_item(archived, m.id) { out.push(m) }
    }
    out
}

fn unread_count(){
    let n = 0
    for m in inbox() { if m.unread { n = n + 1 } }
    n
}

fn inbox_count(){ inbox().len() }

fn undo_label(){
    if last_undo == "" { "Nothing to undo" } else { "Undo " + last_undo_label }
}

fn stamp(kind, label){
    last_undo = kind
    last_undo_label = label
    status = label + " - demo, stored on this device only."
}

fn set_depth(d){
    depth = d
    ui.glance.set_visible(d == 0)
    ui.expanded.set_visible(d == 1)
    ui.full.set_visible(d == 2)
    sync_chrome()
}

fn sync_chrome(){
    ui.glance_body.render()
    ui.expanded_body.render()
    ui.full_body.render()
    ui.status.set_text(status)
    ui.count.set_text("" + inbox_count() + " in Inbox - " + "" + unread_count() + " unread")
    ui.undo_bar.set_visible(last_undo != "")
    ui.undo.set_text(undo_label())
    ui.d0.set_text(pick(depth == 0, "L0 Glance", "L0"))
    ui.d1.set_text(pick(depth == 1, "L1 Expanded", "L1"))
    ui.d2.set_text(pick(depth == 2, "L2 Full app", "L2"))
}

fn pick(cond, on, off){ if cond { on } else { off } }

// ---------- reversible demo actions ----------

fn archive(id){
    let m = msg_of(id)
    if m == nil { return }
    if has_item(archived, id) { return }
    archived.push(id)
    stamp("Archived", m.subject)
    if sel == id { sel = first_inbox_id() }
    sync_chrome()
}

fn undo_archive(id){
    archived.retain(|x| x != id)
    status = "Restored to Inbox - demo."
    last_undo = ""
    last_undo_label = ""
    sync_chrome()
}

fn undo(){
    if last_undo == "Archived" { undo_archive(last_id) }
    if last_undo == "Sent" { undo_send(last_id) }
}

let last_id = ""

fn archive_current(){
    let m = msg_of(sel)
    if m == nil { return }
    last_id = m.id
    archive(m.id)
}

fn first_inbox_id(){
    let rows = inbox()
    if rows.len() == 0 { return "" }
    rows[0].id
}

fn toggle_read(id){
    for m in msgs { if m.id == id { m.unread = !m.unread } }
    sync_chrome()
}

fn send_demo(){
    let body = draft.trim()
    if body == "" { status = "Nothing to send - write something first."; sync_chrome(); return }
    let id = "s" + "" + (sent.len() + 1)
    sent.push({id: id to: "Ana Ruiz" subject: "Re: Contract renewal" preview: body at: "now" unread: false})
    last_id = id
    last_undo = "Sent"
    last_undo_label = "Send (demo)"
    draft = ""
    ui.input.set_text("")
    status = "Sent (demo) - nothing left this device."
    sync_chrome()
}

fn undo_send(id){
    sent.retain(|s| s.id != id)
    status = "Send (demo) undone - the demo message was removed."
    last_undo = ""
    last_undo_label = ""
    sync_chrome()
}

fn restore_all(){
    archived.clear()
    status = "Restored all demo messages."
    last_undo = ""
    last_undo_label = ""
    if sel == "" { sel = first_inbox_id() }
    sync_chrome()
}

fn pick_row(id){
    sel = id
    if depth < 1 { set_depth(1) } else { sync_chrome() }
}

// ---------- tokens ----------

let ground = #xf2f2f7
let surface = #xffffff
let ink = #x1c1c1e
let ink2 = #x3c3c43
let muted = #x8e8e93
let accent = #x007aff
let danger = #xd70015
let line = #xdedede3
let demo_bg = #xfff3cd
let demo_ink = #x8a0b00

// ---------- widget templates ----------

let Flat = ButtonFlat{height: 44 padding: Inset{left: 10 right: 10}
    draw_bg +: {color: #x00000000 color_hover: #x0000000a color_down: #x00000014 border_size: 0.0}
    draw_text +: {color: accent color_hover: accent color_down: accent text_style +: {font_size: 15}}}

let DangerFlat = ButtonFlat{height: 44 padding: Inset{left: 10 right: 10}
    draw_bg +: {color: #x00000000 color_hover: #x0000000a color_down: #x00000014 border_size: 0.0}
    draw_text +: {color: danger color_hover: danger color_down: danger text_style +: {font_size: 15}}}

let SegOff = ButtonFlat{height: 44 width: Fill padding: Inset{left: 6 right: 6} align: Align{x: 0.5 y: 0.5}
    draw_bg +: {color: #x00000000 color_hover: #x00000000a color_down: #x00000014 border_size: 0.0}
    draw_text +: {color: muted color_hover: ink2 color_down: ink2 text_style +: {font_size: 14}}}

let SegOn = ButtonFlat{height: 44 width: Fill padding: Inset{left: 6 right: 6} align: Align{x: 0.5 y: 0.5}
    draw_bg +: {color: surface color_hover: surface color_down: surface border_size: 0.0 border_color: line draw_bg +: {border_radius: 10.0}}
    draw_text +: {color: ink color_hover: ink color_down: ink text_style +: {font_size: 14 bold: true}}}

let SegOnX = ButtonFlat{height: 44 width: Fill padding: Inset{left: 6 right: 6} align: Align{x: 0.5 y: 0.5}
    draw_bg +: {color: surface border_size: 0.0}
    draw_text +: {color: ink text_style +: {font_size: 14 bold: true}}}

let Panel = View{width: Fill height: Fit flow: Down spacing: 6
    padding: Inset{left: 14 right: 14 top: 12 bottom: 12}
    show_bg: true draw_bg.color: surface draw_bg.border_radius: 16.0}

let Title = Label{width: Fill text: "" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 16}}
let BodyT = Label{width: Fill text: "" draw_text.color: ink2 draw_text.text_style.font_size: 14}
let Cap = Label{text: "" draw_text.color: muted draw_text.text_style.font_size: 12}
let CapFill = Label{width: Fill text: "" draw_text.color: muted draw_text.text_style.font_size: 12}
let Eyebrow = Label{text: "" draw_text.color: demo_ink draw_text.text_style: theme.font_bold{font_size: 11}}

// ---------- body ----------

SolidView{width: Fill height: Fill flow: Down show_bg: true draw_bg.color: ground

    // ---- app chrome (always visible) ----
    View{width: Fill height: Fit flow: Down spacing: 2
        padding: Inset{left: 16 right: 16 top: 14 bottom: 10}
        View{width: Fill height: Fit flow: Right align: Align{y: 0.5} spacing: 8}
            Label{text: "Mail" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 21}}
            View{width: Fill height: 1}
            View{width: Fit height: Fit show_bg: true draw_bg.color: demo_bg draw_bg.border_radius: 6.0
                padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
                Label{text: DEMO draw_text.color: demo_ink draw_text.text_style: theme.font_bold{font_size: 11}}}
        count := Label{width: Fill text: "" draw_text.color: muted draw_text.text_style.font_size: 12}
    }

    // ---- depth bodies ----
    glance := View{width: Fill height: Fill
        glance_body := ScrollYView{width: Fill height: Fill flow: Down spacing: 12
            padding: Inset{left: 16 right: 16 top: 4 bottom: 16}
            on_render: || {
                let rows = inbox()
                if rows.len() == 0 {
                    Panel
                        Eyebrow{text: "INBOX EMPTY"}
                        Label{width: Fill text: "No demo messages" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 16}}
                        BodyT{text: "Everything is archived. Restore the demo set, or open the full app."}
                        View{width: Fill height: Fit flow: Right spacing: 8}
                            Flat{text: "Restore all (demo)" on_click: || restore_all()}
                            Flat{text: "Open full app" on_click: || set_depth(2)}
                } else {
                    let m = rows[0]
                    Panel
                        Eyebrow{text: "MAIL - GLANCE - " + DEMO}
                        View{width: Fill height: Fit flow: Right align: Align{y: 0.5} spacing: 8}
                            Label{width: Fill text: m.from draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 16}}
                            Label{text: m.at draw_text.color: muted draw_text.text_style.font_size: 12}
                        Title{text: m.subject}
                        CapFill{text: m.preview}
                        View{width: Fill height: 1 show_bg: true draw_bg.color: line}
                        View{width: Fill height: Fit flow: Right align: Align{y: 0.5} spacing: 8}
                            Label{width: Fill text: m.folder + " - " + m.tag draw_text.color: muted draw_text.text_style.font_size: 12}
                            Cap{text: pick(m.unread, "Unread", "Read")}
                            Cap{text: pick(m.att, "Attachment", "")}
                            Label{text: "●" draw_text.color: accent draw_text.text_style: theme.font_bold{font_size: 16}}
                }
            }
        }
    }

    expanded := View{width: Fill height: Fill
        expanded_body := ScrollYView{width: Fill height: Fill flow: Down spacing: 12
            padding: Inset{left: 16 right: 16 top: 4 bottom: 16}
            on_render: || {
                let m = msg_of(sel)
                if m == nil {
                    Panel
                        Eyebrow{text: "NOTHING SELECTED"}
                        Label{width: Fill text: "Pick a message in the full app" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 16}}
                        BodyT{text: "This expanded card shows one message. The full app lists the whole demo inbox."}
                        Flat{text: "Open full app" on_click: || set_depth(2)}
                } else {
                    Panel
                        Eyebrow{text: "EXPANDED - " + DEMO}
                        View{width: Fill height: Fit flow: Right align: Align{y: 0.5} spacing: 8}
                            Label{width: Fill text: m.from draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 16}}
                            Label{text: m.at draw_text.color: muted draw_text.text_style.font_size: 12}
                        Title{text: m.subject}
                        CapFill{text: m.folder + " - " + m.tag + " - " + pick(m.att, "1 attachment", "no attachment")}
                        View{width: Fill height: 1 show_bg: true draw_bg.color: line}
                        BodyT{text: m.body}
                    Panel
                        View{width: Fill height: Fit flow: Right spacing: 8}
                            DangerFlat{text: "Archive" on_click: || archive_current()}
                            Flat{text: pick(m.unread, "Mark read", "Mark unread") on_click: || toggle_read(m.id)}
                        View{width: Fill height: Fit flow: Right spacing: 8}
                            Flat{text: "Open full app" on_click: || set_depth(2)}
                            Flat{text: "Glance" on_click: || set_depth(0)}
                        CapFill{text: "Archive is reversible: Undo stays in the bottom bar until the next action."}
                }
            }
        }
    }

    full := View{width: Fill height: Fill
        full_body := ScrollYView{width: Fill height: Fill flow: Down spacing: 12
            padding: Inset{left: 16 right: 16 top: 4 bottom: 16}
            on_render: || {
                let rows = inbox()
                Panel
                    Eyebrow{text: "INBOX - " + DEMO}
                    Title{text: "Demo inbox"}
                    CapFill{text: "Synthetic messages, local to this app. Nothing is fetched and nothing is sent."}
                if rows.len() == 0 {
                    Panel
                        BodyT{text: "Inbox is empty - every demo message is archived."}
                        Flat{text: "Restore all (demo)" on_click: || restore_all()}
                }
                for m in rows {
                    Panel
                        View{width: Fill height: Fit flow: Right align: Align{y: 0.5} spacing: 8}
                            Label{width: Fill text: m.from draw_text.color: pick(m.unread, ink, ink2)
                                draw_text.text_style: theme.font_bold{font_size: 16}}
                            Label{text: m.at draw_text.color: muted draw_text.text_style.font_size: 12}
                        Title{text: m.subject}
                        CapFill{text: m.preview}
                        View{width: Fill height: Fit flow: Right spacing: 8}
                            Flat{text: pick(m.unread, "Mark read", "Mark unread") on_click: || toggle_read(m.id)}
                            Flat{text: "Archive" on_click: || archive(m.id)}
                    }
                }
                Panel
                    Eyebrow{text: "COMPOSE - DRAFT STAYS LOCAL"}
                    input := TextInput{width: Fill height: 44 text: ""
                        draw_bg.color: surface draw_text.color: ink
                        on_change: |t| { draft = t }}
                    View{width: Fill height: Fit flow: Right spacing: 8}
                        Flat{text: "Send (demo)" on_click: || send_demo()}
                        Flat{text: "Clear" on_click: || { draft = ""; ui.input.set_text("") }}
                    CapFill{text: "Send (demo) only appends to this list. There is no mailbox and no send."}
                if sent.len() > 0 {
                    Panel
                        Eyebrow{text: "SENT - DEMO"}
                        for s in sent {
                            View{width: Fill height: Fit flow: Down spacing: 2}
                                Title{text: "To " + s.to + " - " + s.subject}
                                CapFill{text: s.preview}
                        }
                    }
                }
            }
        }
    }

    // ---- bottom bar: depth nav + status + undo ----
    View{width: Fill height: Fit flow: Down spacing: 4
        padding: Inset{left: 16 right: 16 top: 6 bottom: 10}
        View{width: Fill height: 1 show_bg: true draw_bg.color: line}
        View{width: Fill height: Fit flow: Right spacing: 6}
            d0 := SegOnX{text: "L0 Glance" on_click: || set_depth(0)}
            d1 := SegOnX{text: "L1 Expanded" on_click: || set_depth(1)}
            d2 := SegOnX{text: "L2 Full app" on_click: || set_depth(2)}
        View{width: Fill height: Fit flow: Right align: Align{y: 0.5} spacing: 8}
            status := Label{width: Fill text: "" draw_text.color: ink2 draw_text.text_style.font_size: 12}
            undo_bar := View{width: Fit height: Fit}
                undo := ButtonFlat{height: 44 width: Fit padding: Inset{left: 12 right: 12} align: Align{x: 0.5 y: 0.5}
                    draw_bg +: {color: #x00000000 color_hover: #x0000000a color_down: #x00000014 border_size: 0.0}
                    draw_text +: {color: accent color_hover: accent color_down: accent text_style +: {font_size: 14}}
                    on_click: || undo()}
    }
}

fn boot(){
    set_depth(0)
}
start_timeout(0.05, || boot())

