# ledger mail.glance@0.1.0
# level:   L0
# profile: ui/l0
# model:   dev.studio.cards.mail
#
# MAIL family's L0 glance. The reusable declarative half of the Mail template;
# the L1 expanded and L2 full views live in the native bundle
# (card-templates/mail/bundle/main.splash, views `l1_expanded` / `l2_full`).
#
# L0/L1/L2 here are PRESENTATION depths, not parser levels — this file is L0
# because it is a glance card, and the language level stays L0 at every depth.
#
# Fixture: glance.data.json. Every record there is synthetic demo data; no
# mailbox is read, no account is used, nothing is sent. The card therefore says
# DEMO in its own eyebrow rather than implying a live mailbox.

# TWO sources, not one sliced two ways (news.card's rule). The glance shows the
# lead message; the count row is its own source, so refetching one never has to
# discard the other.
source lead  sys.dataset(id: "m1", fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value])
source inbox sys.dataset(id: "m1", fields: [title, subtitle, as_of, status])

# Presentation depth, kept as card state so one source serves all three views.
state depth      { shape: enum[glance, expanded, full], initial: .glance }
state sel        { shape: text, initial: "m1" }
state archived   { shape: text, initial: "" }
state view_unread { shape: bool, initial: true }

event open_msg     { sel: set($value), depth: set(.expanded) }
event open_full    { depth: set(.full) }
event back_glance  { depth: set(.glance) }
event toggle_read  { view_unread: set($value) }
event archive      { archived: set($value) }
event undo_archive { archived: clear }

# Vocabulary — the card's own fixed words.
copy app       { class: vocabulary, en: "Mail",          zh: "邮件" }
copy eyebrow   { class: vocabulary, en: "MAIL · GLANCE · DEMO", zh: "邮件 · 概览 · 演示" }
copy unread    { class: vocabulary, en: "Unread",        zh: "未读" }
copy open      { class: vocabulary, en: "Open (demo)",   zh: "打开（演示）" }
copy full      { class: vocabulary, en: "Full app",      zh: "完整应用" }
copy mark_r    { class: vocabulary, en: "Mark read",     zh: "标为已读" }
copy archive   { class: vocabulary, en: "Archive (demo)", zh: "归档（演示）" }
copy undo      { class: vocabulary, en: "Undo",          zh: "撤销" }
copy subject   { class: vocabulary, en: "Inbox" }

# States are declared copy, never inline strings (framework-l0 §1).
copy loading   { class: vocabulary, en: "Loading demo messages…", zh: "正在加载演示邮件…" }
copy offline   { class: vocabulary, en: "Can't load demo messages", zh: "无法加载演示邮件" }
copy empty     { class: vocabulary, en: "No demo messages", zh: "没有演示邮件" }
copy empty_h   { class: vocabulary, en: "Everything is archived (demo).", zh: "所有邮件已归档（演示）。" }
copy demo_note { class: vocabulary, en: "Demo data. No mailbox, no account, no send.", zh: "演示数据。无邮箱、无账号、不会发送。" }
copy as_of_note { class: vocabulary, en: "Inbox" }

view root Surface(pad: .tight) {
  Col(gap: 10) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(value: lead.as_of)
    }
    TextEyebrow(text: copy.eyebrow)
    when lead.$state == .pending { TextBody(text: copy.loading) }
    when lead.$state == .failed  { TextBody(text: copy.offline) }
    when lead.$state == .ready   {
      TextTitle(text: lead.title, width: .fill)
      TextRow(text: lead.subtitle, width: .fill)
      Rule
      Row(gap: 8, align: .center) {
        Chip(text: copy.mark_r, on_tap: toggle_read, value: .read)
        Chip(text: copy.open, on_tap: open_msg, value: "m1", tone: .primary)
        Chip(text: copy.full, on_tap: open_full, tone: .primary)
      }
      Row(gap: 8, align: .center) {
        Chip(text: copy.archive, on_tap: archive, value: "m1", tone: .danger)
        Chip(text: copy.undo, on_tap: undo_archive, tone: .primary)
      }
      TextCaption(text: copy.demo_note, width: .fill)
    }
    when inbox.$state == .ready {
      Rule
      Row(gap: 8, align: .center) {
        TextCaption(text: inbox.subtitle, width: .fill)
        TextCaption(value: inbox.as_of)
      }
    }
  }
}

// Mail card template — dev.studio.cards.mail
// All records are SYNTHETIC DEMO DATA held in this app's local list.
// No mailbox, no account, no network. "Send (demo)" appends to the local
// demo Sent list only; nothing is ever transmitted.
//
// Depths are PRESENTATION depths (UI), not parser levels:
//   L0  compact glance card
//   L1  expanded actionable card
//   L2  full app view (reader + demo inbox + reply composer)

let msgs = [
    {id: "m1" from: "Ana Ruiz" subject: "Contract renewal - signature by Friday"
        preview: "The revised payment terms are in the attached PDF. Can you confirm we can sign by Friday?"
        body: "The revised payment terms are in the attached PDF. Two changes since the last draft: net 45 instead of net 30, and the renewal window moves to 60 days. Can you confirm whether we can sign by Friday? I need to tell the accountant before the end of the week."
        at: "09:12" folder: "Inbox" tag: "Work" att: true unread: true}
    {id: "m2" from: "City Library" subject: "Hold ready: your request is available"
        preview: "Three books from your request are on the holds shelf until Saturday."
        body: "Three books from your request are on the holds shelf until Saturday. The reading room closes at 20:00. Please bring your library card to collect them."
        at: "08:47" folder: "Inbox" tag: "Personal" att: false unread: true}
    {id: "m3" from: "Priya N." subject: "Design review moved to Thursday 10:00"
        preview: "Pushed to Thursday so Marcus can join. Same room, notes in the shared doc."
        body: "Pushed the design review to Thursday 10:00 so Marcus can join. Same room as before. The notes are in the shared doc, and the agenda is at the top."
        at: "Yesterday" folder: "Inbox" tag: "Work" att: false unread: false}
    {id: "m4" from: "Northwind Studio" subject: "Invoice 2291 - August retainer"
        preview: "Amount due 1,480.00, payable within 14 days. Details in the PDF statement."
        body: "Invoice 2291 for the August retainer is attached. Amount due 1,480.00, payable within 14 days. Bank details are unchanged from last month."
        at: "Mon" folder: "Inbox" tag: "Finance" att: true unread: false}
]

let ground = #xf2f2f7
let surface = #xffffff
let ink = #x1c1c1e
let ink2 = #x3c3c43
let muted = #x8e8e93
let accent = #x007aff
let danger = #xd70015
let line = #xe5e5ea
let demo_bg = #xfff3cd
let demo_ink = #x8a0b00

let archived = []
let drafts = []
let sent = []
let last_id = ""
let status = "Demo inbox."
let depth = 0
let sel = "m1"

// ---------- state helpers ----------

fn has_item(list, x){ for v in list { if v == x { return true } } false }

fn pick(cond, on, off){ if cond { on } else { off } }

fn msg_of(id){
    for m in msgs { if m.id == id { return m } }
    nil
}

fn n_rows(){
    let n = 0
    for m in msgs { if !has_item(archived, m.id) { n = n + 1 } }
    n
}

fn n_unread(){
    let n = 0
    for m in msgs { if !has_item(archived, m.id) && m.unread { n = n + 1 } }
    n
}

fn lead(){
    for m in msgs { if !has_item(archived, m.id) { return m } }
    nil
}

fn unread_str(id){
    for m in msgs {
        if m.id == id {
            if m.unread { return "Unread" }
            return "Read"
        }
    }
    ""
}

// A draft belongs to the message it was typed for, so selecting a different
// message never shows another one's text.
fn draft_of(id){
    for d in drafts { if d.id == id { return d.text } }
    ""
}

fn set_draft(id, t){
    for d in drafts { if d.id == id { d.text = t; return } }
    drafts.push({id: id text: t})
}

fn say(s){ status = s; ui.status.set_text(s) }

fn depth_name(){
    if depth == 0 { return "L0 · compact glance" }
    if depth == 1 { return "L1 · expanded card" }
    return "L2 · full app"
}

fn set_depth(d){
    depth = d
    say("Showing " + depth_name())
    sync()
}

// ---------- local actions ----------

fn do_archive(id){
    if has_item(archived, id) { return }
    archived.push(id)
    last_id = id
    say("Archived (demo) · tap Undo")
    sync()
}

fn do_undo(){
    if last_id == "" { say("Nothing to undo."); return }
    if !has_item(archived, last_id) { last_id = ""; say("Nothing to undo."); return }
    archived.retain(|x| x != last_id)
    last_id = ""
    say("Restored to Inbox (demo)")
    sync()
}

fn do_read(id){
    for m in msgs { if m.id == id { m.unread = !m.unread } }
    if unread_str(id) == "Unread" { say("Marked unread (demo)") } else { say("Marked read (demo)") }
    sync()
}

fn do_open(id){
    sel = id
    set_depth(1)
}

// L1's route to the composer in L2.
fn do_reply(id){
    sel = id
    set_depth(2)
}

fn do_send(){
    let m = msg_of(sel)
    if m == nil { say("Pick a message first"); return }
    if has_item(archived, m.id) { say("Unarchive before replying (demo)"); return }
    let body = draft_of(m.id).trim()
    if body == "" { say("Nothing to send · write a reply first"); return }
    sent.push({to: m.from subject: "Re: " + m.subject preview: body})
    set_draft(m.id, "")
    say("Sent (demo) to " + m.from)
    sync()
}

// ---------- chrome sync ----------

fn sync(){
    ui.glance.set_visible(depth == 0)
    ui.expanded.set_visible(depth == 1)
    ui.full.set_visible(depth == 2)

    ui.count.set_text("" + n_rows() + " in Inbox · " + "" + n_unread() + " unread")
    ui.depth_now.set_text("Showing " + depth_name())

    let m = lead()
    if m == nil {
        ui.g_card.set_visible(false)
        ui.g_empty.set_visible(true)
    } else {
        ui.g_card.set_visible(true)
        ui.g_empty.set_visible(false)
        ui.g_from.set_text(m.from)
        ui.g_time.set_text(m.at)
        ui.g_subj.set_text(m.subject)
        ui.g_prev.set_text(m.preview)
        ui.g_meta.set_text(m.tag + " · " + pick(m.unread, "Unread", "Read"))
    }

    let s = msg_of(sel)
    let s_ok = false
    if s != nil && !has_item(archived, s.id) { s_ok = true }
    ui.x_card.set_visible(s_ok)
    ui.x_empty.set_visible(!s_ok)
    if s_ok {
        ui.x_from.set_text(s.from)
        ui.x_time.set_text(s.at)
        ui.x_subj.set_text(s.subject)
        ui.x_meta.set_text(s.tag + " · " + pick(s.unread, "Unread", "Read") + " · " + pick(s.att, "1 attachment", "no attachment"))
        ui.x_prev.set_text(s.preview)
    }

    ui.r1.set_visible(!has_item(archived, "m1"))
    ui.r2.set_visible(!has_item(archived, "m2"))
    ui.r3.set_visible(!has_item(archived, "m3"))
    ui.r4.set_visible(!has_item(archived, "m4"))
    ui.r1_u.set_text(unread_str("m1"))
    ui.r2_u.set_text(unread_str("m2"))
    ui.r3_u.set_text(unread_str("m3"))
    ui.r4_u.set_text(unread_str("m4"))

    // reader + composer follow the selection
    let r = msg_of(sel)
    if r != nil {
        ui.rd_from.set_text(r.from)
        ui.rd_subj.set_text(r.subject)
        ui.rd_body.set_text(r.body)
        ui.cmp_to.set_text("To " + r.from + " · Re: " + r.subject)
    }
    ui.field.set_text(draft_of(sel))

    if sent.len() > 0 {
        ui.sent_card.set_visible(true)
        let last = sent[sent.len() - 1]
        ui.sent_count.set_text("" + sent.len())
        ui.sent_to.set_text("To " + last.to + " · " + last.subject)
        ui.sent_prev.set_text(last.preview)
    } else {
        ui.sent_card.set_visible(false)
    }
}

